/**
 * WPMN Design System — bundle generator
 *
 * Merges the four token CSS sources into one wpmn-bundle.css in cascade order,
 * with an activation header. One file = nothing gets dropped by a connector's
 * file-import cap, and no missing pieces.
 *
 * Run: node scripts/build-bundle.mjs   (rerun after editing any source)
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const ORDER = ['primitives.css', 'brand-primitives.css', 'tokens.css', 'typography.css'];

const BRANDS = [
  'wpmanagenia', 'fluentforms', 'fluentcrm', 'ninjatables', 'fluentcommunity',
  'fluentbooking', 'paymattic', 'fluentboards', 'fluentsmtp', 'fluentsupport',
  'fluentaffiliate', 'azonpress', 'wpsocialninja', 'fluentcart', 'fluentplayer', 'fluentmembers'
];

const header = `/* ============================================================================
   WPMN DESIGN SYSTEM — wpmn-bundle.css  (single compiled file)
   ----------------------------------------------------------------------------
   Everything in one file, in cascade order:
     1. primitives        raw values for the default brand (WPManageNinja)
     2. brand-primitives  per-brand overrides via [data-brand="..."]
     3. tokens            semantic tokens — USE THESE in your markup
     4. typography        type scale + .text-* utility classes

   GENERATED by scripts/build-bundle.mjs — do not hand-edit; edit the source
   files and rerun the generator.

   ────────────────────────────────────────────────────────────────────────
   1) ACTIVATE A BRAND  (REQUIRED — without this you get default WPMN blue)
   ────────────────────────────────────────────────────────────────────────
     Put data-brand on <html> (or any ancestor):
        <html data-brand="fluentforms"> … </html>

     Brand keys:
        ${BRANDS.join(', ')}

   2) DARK MODE     add data-theme="dark" to <html>
   3) MOBILE        handled automatically at @media (max-width: 768px)

   ────────────────────────────────────────────────────────────────────────
   4) USE TOKENS — NEVER RAW VALUES  (the real names are all in this file —
      grep here, never guess a name)
   ────────────────────────────────────────────────────────────────────────
     text color    var(--color-text-primary)          (…-invert on dark surfaces)
     surfaces      var(--color-surface-primary | -secondary | -alt)
     type          USE the .text-* classes in markup (.text-h1 … .text-h6, .text-body-large |
                   -base | -small) — they auto-swap at 768px. The --font-size-* vars are the
                   same values, only for custom CSS where a class can't be used.
     spacing       var(--primitive-space-8 … -120)     (8/12/16/20/24/32/40/48/64/80/96/120)
     radius        var(--radius-xsm | -sm | -md | -lg)  = 8/12/16/32px (these 4 semantic
                   tokens only; do NOT use --primitive-radius-*; there is no --radius-xxs)
     buttons       var(--btn-bg-enable) + invert text  (or use .wpmn-btn--primary)

   Components + class names: see COMPONENTS.md.  Sections: see registry.json + llms.txt.
   ============================================================================ */
`;

let out = header;
for (const f of ORDER) {
  const css = readFileSync(join(ROOT, f), 'utf8').trim();
  out += `\n\n/* ==== ${f} ${'='.repeat(Math.max(0, 64 - f.length))} */\n${css}\n`;
}
writeFileSync(join(ROOT, 'wpmn-bundle.css'), out);
console.log('wpmn-bundle.css written:', out.length, 'chars from', ORDER.join(' + '));
